-- =============================================================================
-- Migration 0064: Examentraining — inhoud om de y-as
-- =============================================================================
-- Gegenereerd door scripts/examen-inhoud-y-as.ts — niet met de hand bewerken.
--
-- Eigen onderdeel Examentraining, geen theoriehoofdstuk uit het boek.
-- De inhoud van het lichaam dat ontstaat als een vlakdeel om de y-as wentelt.
-- Acht vragen niveau 3. Vier met de y-waarden in de zin, vier waarbij
-- je die y-waarden zelf zoekt.
--
-- Eigen oefenvragen, geen boek- of examenopgaven. Elke integraal wordt
-- nagerekend door src/content/primitieven.test.ts
-- (content/hoofdstuk-examen/inhoud-om-de-y-as.json).
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 2 topics, 2 clusters
--   • 8 vragen met elk 4 stappen (32 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('examentraining', $examentrainingsql$Examentraining$examentrainingsql$, 5, 16, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'examentraining' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('examen_inhoud_yas', $examentrainingsql$Inhoud om de y-as$examentrainingsql$, 7, 'toepassingen'),
  ('examen_inhoud_yas_grenzen', $examentrainingsql$Inhoud om de y-as, grenzen zelf$examentrainingsql$, 8, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$y-waarden gegeven$examentrainingsql$, 1),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$y-waarden zelf zoeken$examentrainingsql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
  (site, topic_id, cluster_id, latex_body, answer, latex_answer, difficulty, order_index, is_ai_generated, answer_alternatives)
SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y^{2} + 2$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(83/15)pi$examentrainingsql$, $examentrainingsql$\dfrac{83}{15}\pi$examentrainingsql$, 3, 1, ARRAY[$examentrainingsql$(83/15)*pi$examentrainingsql$, $examentrainingsql$83pi/15$examentrainingsql$]::text[]),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 5}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(9+8ln(2))pi$examentrainingsql$, $examentrainingsql$(9 + 8\ln(2))\pi$examentrainingsql$, 3, 2, ARRAY[$examentrainingsql$pi*(9+8ln(2))$examentrainingsql$, $examentrainingsql$9pi+8pi*ln(2)$examentrainingsql$]::text[]),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{y/2}$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(e^2-1)pi$examentrainingsql$, $examentrainingsql$(e^{2} - 1)\pi$examentrainingsql$, 3, 3, ARRAY[$examentrainingsql$pi*(e^2-1)$examentrainingsql$, $examentrainingsql$pi*e^2-pi$examentrainingsql$]::text[]),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 1 + \ln(y)$, de $y$-as en de lijnen $y = 1$ en $y = e$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(2e-1)pi$examentrainingsql$, $examentrainingsql$(2e - 1)\pi$examentrainingsql$, 3, 4, ARRAY[$examentrainingsql$pi*(2e-1)$examentrainingsql$, $examentrainingsql$2*e*pi-pi$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{4x + 1}$, de $y$-as en de lijn $y = 3$. De bovenste $y$-waarde is $3$. Zoek zelf de onderste $y$-waarde, waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(31/15)pi$examentrainingsql$, $examentrainingsql$\dfrac{31}{15}\pi$examentrainingsql$, 3, 1, ARRAY[$examentrainingsql$(31/15)*pi$examentrainingsql$, $examentrainingsql$31pi/15$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 2\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$2pi^2$examentrainingsql$, $examentrainingsql$2\pi^{2}$examentrainingsql$, 3, 2, ARRAY[$examentrainingsql$2*pi^2$examentrainingsql$, $examentrainingsql$pi^2*2$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 8 - 2x^{2}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$16pi$examentrainingsql$, $examentrainingsql$16\pi$examentrainingsql$, 3, 3, ARRAY[$examentrainingsql$16*pi$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/4)pi^2$examentrainingsql$, $examentrainingsql$\dfrac{1}{4}\pi^{2}$examentrainingsql$, 3, 4, ARRAY[$examentrainingsql$pi^2/4$examentrainingsql$, $examentrainingsql$(pi^2)/4$examentrainingsql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y^{2} + 2$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $0$ tot $1$. Op dat stuk is $f(y) \ge 2$, dus de grafiek ligt rechts van de $y$-as. De straal is $f(y)$. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y^{2} + 2$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{1} (y^{2} + 2)^{2}\,\mathrm{d}y$. Werk het kwadraat uit: dat is $\pi \displaystyle\int_{0}^{1} (y^{4} + 4y^{2} + 4)\,\mathrm{d}y$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y^{2} + 2$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(y) = \pi\left(\dfrac{1}{5}y^{5} + \dfrac{4}{3}y^{3} + 4y\right)$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y^{2} + 2$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \pi\left(\dfrac{1}{5} + \dfrac{4}{3} + 4\right)$. Dat is $\dfrac{83}{15}\pi$. De inhoud is $\dfrac{83}{15}\pi$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 5}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $0$ tot $1$. Op dat stuk zijn teller en noemer positief, dus de grafiek ligt rechts van de $y$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$. Schrijf de breuk eerst als een getal plus een rest.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 5}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$y + 5 = 1\cdot(y + 1) + 4$, dus $f(y) = 1 + \dfrac{4}{y + 1}$. Het kwadraat is $1 + \dfrac{8}{y + 1} + \dfrac{16}{(y + 1)^{2}}$. $I(L)$ is $\pi$ keer de integraal daarvan van $0$ tot $1$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 5}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$De kern is $y + 1$, met afgeleide $1$. Een primitieve is $F(y) = \pi\left(y + 8\ln(y + 1) - \dfrac{16}{y + 1}\right)$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 5}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) = \pi(8\ln(2) - 7)$ en $F(0) = -16\pi$. Het verschil is $(9 + 8\ln(2))\pi$. De inhoud is $(9 + 8\ln(2))\pi$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{y/2}$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $0$ tot $2$. $e^{y/2}$ is overal positief, dus de grafiek ligt rechts van de $y$-as. Het kwadraat is $e^{y}$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{y/2}$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{2} \left(e^{y/2}\right)^{2}\,\mathrm{d}y$. Dat is $\pi \displaystyle\int_{0}^{2} e^{y}\,\mathrm{d}y$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{y/2}$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi e^{y}$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{y/2}$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(2) - F(0) = \pi e^{2} - \pi = (e^{2} - 1)\pi$. De inhoud is $(e^{2} - 1)\pi$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 1 + \ln(y)$, de $y$-as en de lijnen $y = 1$ en $y = e$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $1$ tot $e$. Op dat stuk is $\ln(y) \ge 0$, dus $f(y) \ge 1$ en de grafiek ligt rechts van de $y$-as. De inhoud is $\pi$ keer de integraal van $(1 + \ln(y))^{2}$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 1 + \ln(y)$, de $y$-as en de lijnen $y = 1$ en $y = e$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$(1 + \ln(y))^{2} = 1 + 2\ln(y) + (\ln(y))^{2}$. $I(L)$ is $\pi$ keer de integraal daarvan van $1$ tot $e$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 1 + \ln(y)$, de $y$-as en de lijnen $y = 1$ en $y = e$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van $\ln(y)$ is $y\ln(y) - y$. Een primitieve van $(\ln(y))^{2}$ is $y(\ln(y))^{2} - 2y\ln(y) + 2y$. Die tel je bij elkaar op. Een primitieve van de integrand is $F(y) = \pi\bigl(y(\ln(y))^{2} + y\bigr)$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 1 + \ln(y)$, de $y$-as en de lijnen $y = 1$ en $y = e$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(e) = 2e\pi$ en $F(1) = \pi$. Het verschil is $(2e - 1)\pi$. De inhoud is $(2e - 1)\pi$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{4x + 1}$, de $y$-as en de lijn $y = 3$. De bovenste $y$-waarde is $3$. Zoek zelf de onderste $y$-waarde, waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De bovenste $y$-waarde is $3$. Op de $y$-as is $x = 0$, dus $f(0) = \sqrt{1} = 1$. Dat is de onderste $y$-waarde. Uit $y = \sqrt{4x + 1}$ volgt $x = \dfrac{y^{2} - 1}{4}$, met $x \ge 0$. De inhoud is $\pi$ keer de integraal van $x^{2}$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{4x + 1}$, de $y$-as en de lijn $y = 3$. De bovenste $y$-waarde is $3$. Zoek zelf de onderste $y$-waarde, waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{1}^{3} \left(\dfrac{y^{2} - 1}{4}\right)^{2}\,\mathrm{d}y$. Dat is $\pi$ keer de integraal van $\dfrac{y^{4} - 2y^{2} + 1}{16}$ van $1$ tot $3$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{4x + 1}$, de $y$-as en de lijn $y = 3$. De bovenste $y$-waarde is $3$. Zoek zelf de onderste $y$-waarde, waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \dfrac{\pi}{16}\left(\dfrac{1}{5}y^{5} - \dfrac{2}{3}y^{3} + y\right)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{4x + 1}$, de $y$-as en de lijn $y = 3$. De bovenste $y$-waarde is $3$. Zoek zelf de onderste $y$-waarde, waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$Noem het stuk tussen haakjes $G(y)$. Bij $y = 3$ is $18 - 3 = 15$, dus $G(3) = \dfrac{243}{5} - 15 = \dfrac{168}{5}$. $G(1) = \dfrac{8}{15}$. Het verschil is $\dfrac{496}{15}$. Deel door $16$ en vermenigvuldig met $\pi$: de inhoud is $\dfrac{31}{15}\pi$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 2\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. $2\sin(y) = 0$ als $\sin(y) = 0$. De kleinste twee niet-negatieve oplossingen zijn $y = 0$ en $y = \pi$. Daartussen is $\sin(y) \ge 0$, dus de grafiek ligt rechts van de $y$-as of erop. De straal is $2\sin(y)$. De inhoud is $\pi$ keer de integraal van het kwadraat.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 2\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{\pi} (2\sin(y))^{2}\,\mathrm{d}y$. Dat is $\pi$ keer de integraal van $4\sin^{2}(y)$ van $0$ tot $\pi$. Gebruik $\sin^{2}(y) = \dfrac{1 - \cos(2y)}{2}$, dus $4\sin^{2}(y) = 2 - 2\cos(2y)$. De kern van de cosinus is $2y$, met afgeleide $2$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 2\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = 2\pi y - \pi\sin(2y)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 2\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(\pi) = 2\pi^{2}$ en $F(0) = 0$. De inhoud is $2\pi^{2}$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 8 - 2x^{2}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafiek snijdt de $y$-as in $(0, 8)$. Hij snijdt de $x$-as waar $8 - 2x^{2} = 0$, dus $x^{2} = 4$. In het eerste kwadrant is $x = 2$, en daar is $y = 0$. $V$ ligt dus tussen $y = 0$ en $y = 8$. Uit $y = 8 - 2x^{2}$ volgt $x^{2} = \dfrac{8 - y}{2}$. De inhoud is $\pi$ keer de integraal van $x^{2}$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 8 - 2x^{2}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{8} \dfrac{8 - y}{2}\,\mathrm{d}y$. Dat is $\pi$ keer de integraal van $4 - \dfrac{1}{2}y$ van $0$ tot $8$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 8 - 2x^{2}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi\left(4y - \dfrac{1}{4}y^{2}\right)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 8 - 2x^{2}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(8) - F(0) = \pi\left(32 - 16\right) = 16\pi$. De inhoud is $16\pi$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De onderste $y$-waarde is $0$. $\cos(y) = 0$ bij $y = \dfrac{\pi}{2}$, en dat is de kleinste positieve oplossing. Daartussen is $\cos(y) > 0$, dus de grafiek ligt rechts van de $y$-as. De straal is $\cos(y)$. De inhoud is $\pi$ keer de integraal van $\cos^{2}(y)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$Gebruik $\cos^{2}(y) = \dfrac{1 + \cos(2y)}{2}$. $I(L)$ is $\pi$ keer de integraal daarvan van $0$ tot $\dfrac{\pi}{2}$. De kern van de cosinus is $2y$, met afgeleide $2$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi\left(\dfrac{1}{2}y + \dfrac{1}{4}\sin(2y)\right)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F\left(\dfrac{\pi}{2}\right) - F(0) = \pi \cdot \dfrac{\pi}{4} = \dfrac{1}{4}\pi^{2}$. De inhoud is $\dfrac{1}{4}\pi^{2}$.$examentrainingsql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_yas' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_yas' AND site = 'integralen'));
  IF n <> 4 THEN RAISE EXCEPTION 'Cluster examen_inhoud_yas hoort 4 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_yas_grenzen' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_yas_grenzen' AND site = 'integralen'));
  IF n <> 4 THEN RAISE EXCEPTION 'Cluster examen_inhoud_yas_grenzen hoort 4 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('examen_inhoud_yas', 'examen_inhoud_yas_grenzen');
  IF n <> 32 THEN RAISE EXCEPTION 'Deze topics horen samen 32 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
